<?php
declare(strict_types=1);
if(!defined('_GNUBOARD_')&&PHP_SAPI!=='cli'){http_response_code(403);exit;}
require_once __DIR__.'/toss-core.php';require_once __DIR__.'/vip-store-core.php';
function ny_id(string $kind,string $id):string{return 'N'.substr(hash('sha256',$kind.':'.$id),0,19);}
function ny_catalog():array{
 $out=[];
 foreach(nt_products()as $p){$id=ny_id('points',$p['id']);$out[$id]=['id'=>$id,'source'=>'points','sourceId'=>$p['id'],'title'=>number_format($p['paidPoints']).'P 포인트 충전권','price'=>$p['priceWon'],'points'=>$p['totalPoints'],'image'=>'/noa-assets/points-'.$p['id'].'.webp','description'=>'기본 '.number_format($p['paidPoints']).'P + 추가 '.number_format($p['bonusPoints']).'P','orderable'=>true];}
 foreach(nv_products()as $p){$id=ny_id('vip',$p['id']);$out[$id]=['id'=>$id,'source'=>'vip','sourceId'=>$p['id'],'title'=>$p['name'],'price'=>$p['points'],'plan'=>$p['plan'],'days'=>$p['durationDays'],'image'=>$p['image'],'description'=>$p['durationDays'].'일 이용권','orderable'=>true];}
 require_once __DIR__.'/ecosystem-shop.php';foreach(eco_products()as $p){$id=ny_id('goods',$p['id']);$out[$id]=['id'=>$id,'source'=>'goods','sourceId'=>$p['id'],'title'=>$p['title'],'price'=>$p['priceWon'],'image'=>$p['image'],'description'=>$p['description']??'','orderable'=>false,'sourceUrl'=>$p['url'],'optionNote'=>$p['optionNote']??'','shippingNote'=>$p['shippingNote']??''];$native=ns_one('SELECT it_use,it_stock_qty,it_10 FROM '.ns_table('g5_shop_item_table').' WHERE it_id='.ns_e($id));if($native&&$native['it_10']==='noa:goods:'.$p['id']&&(int)$native['it_use']===1&&(int)$native['it_stock_qty']>0)$out[$id]['orderable']=true;}return $out;
}
function ny_benefits(array $catalog,array $lines):array{
 if(!$lines||count($lines)>50)throw new DomainException('invalid_cart');$out=['amount'=>0,'points'=>0,'plan'=>null,'days'=>0,'items'=>[]];$seen=[];
 foreach($lines as $r){$id=$r['id']??'';$n=$r['quantity']??0;$price=$r['price']??-1;
 if(!is_string($id)||!isset($catalog[$id])||isset($seen[$id])||!is_int($n)||$n<1||$n>10||!is_int($price)||$price!==$catalog[$id]['price'])throw new DomainException('cart_changed');
 $p=$catalog[$id];if(!$p['orderable']||$p['source']==='goods')throw new DomainException('goods_options_shipping_required');$seen[$id]=true;$out['amount']+=$price*$n;$out['points']+=($p['points']??0)*$n;
 if($p['source']==='vip'){if($out['plan']!==null&&$out['plan']!==$p['plan'])throw new DomainException('mixed_membership');$out['plan']=$p['plan'];$out['days']+=$p['days']*$n;}$out['items'][]=['id'=>$id,'quantity'=>$n,'price'=>$price];}return $out;
}
function ny_validate_paid(array $o,array $s):void{
 if(($s['mode']??'')==='points'){if($s['benefits']['points']!==0||$s['benefits']['plan']===null||($o['mb_id']??'')!==$s['owner']||($o['od_id']??'')!==$s['order']||!in_array($o['od_status']??'',['입금','준비','배송','완료'],true)||(int)($o['od_receipt_price']??-1)!==0||(int)($o['od_receipt_point']??-1)!==$s['benefits']['amount']||(int)($o['od_cancel_price']??-1)!==0||(int)($o['od_misu']??-1)!==0)throw new DomainException('payment_unverified');return;}if(($s['mode']??'')!=='live')throw new DomainException('test_no_fulfillment');
 if(($o['mb_id']??'')!==$s['owner']||($o['od_id']??'')!==$s['order']||($o['od_pg']??'')!=='kcp'||!in_array($o['od_status']??'',['입금','준비','배송','완료'],true)||!preg_match('/^[0-9]{14}$/D',(string)($o['od_tno']??''))||(int)($o['od_receipt_price']??-1)!==$s['benefits']['amount']||(int)($o['od_receipt_point']??-1)!==0||(int)($o['od_cancel_price']??-1)!==0||(int)($o['od_misu']??-1)!==0)throw new DomainException('payment_unverified');
}
function ny_capture():void{
 global $member,$default,$config;$owner=(string)($member['mb_id']??'');$id=(string)get_session('ss_order_id');$cart=(string)get_session(!empty($_POST['sw_direct'])?'ss_cart_direct':'ss_cart_id');$catalog=ny_catalog();
 if(!preg_match('/^[A-Za-z0-9_-]{1,64}$/D',$cart))return;
 $rows=[];$owned=false;$r=ns_q('SELECT it_id,ct_qty,ct_price,io_id,io_price FROM '.ns_table('g5_shop_cart_table').' WHERE od_id='.ns_e($cart)." AND ct_status='쇼핑' AND ct_select='1'");while($v=sql_fetch_array($r)){$owned=$owned||(isset($catalog[$v['it_id']])&&$catalog[$v['it_id']]['source']!=='goods');$rows[]=$v;}if(!$owned)return;
 if($owner===''||!preg_match('/^[0-9]{10,20}$/D',$id))throw new DomainException('native_order_session_required');
 $lines=[];foreach($rows as $v){if($v['io_id']!==''||(int)$v['io_price']!==0)throw new DomainException('cart_changed');$lines[]=['id'=>$v['it_id'],'quantity'=>(int)$v['ct_qty'],'price'=>(int)$v['ct_price']];}$b=ny_benefits($catalog,$lines);
 $usedPoints=(int)($_POST['od_temp_point']??0);$pointMode=$usedPoints>0;if(!$pointMode&&empty($default['de_card_test'])&&empty(ns_doc('youngcart:policy')['data']['liveApproved']))throw new DomainException('live_release_not_approved');if($pointMode&&($b['points']>0||$b['plan']===null||$usedPoints!==$b['amount']))throw new DomainException('mixed_point_payment_not_enabled');
 $m=nr_member($owner,false);if($b['plan']!==null&&(!in_array((int)$m['mb_level'],$b['plan']==='vip'?[2,3,4]:[7,8],true)||$owner===($config['cf_admin']??'')))throw new DomainException('membership_level_required');
 ns_atomic($owner,false,function()use($owner,$id,$b,$default,$pointMode){$k='youngcart:quote:'.$id;$r=ns_doc($k,true);$d=['owner'=>$owner,'order'=>$id,'mode'=>$pointMode?'points':(!empty($default['de_card_test'])?'test':'live'),'benefits'=>$b];if($r){if($r['data']!==$d)throw new DomainException('order_quote_changed');return;}ns_put($k,'youngcart_quote',$d,0,$owner);});
}
function ny_fulfill(string $owner,string $id):array{
 if(!preg_match('/^[0-9]{10,20}$/D',$id))throw new DomainException('invalid_order');
 return ns_atomic($owner,true,function()use($owner,$id){$s=ns_doc('youngcart:quote:'.$id,true)['data']??null;if(!$s||$s['owner']!==$owner)throw new DomainException('order_not_found');$o=ns_one('SELECT * FROM '.ns_table('g5_shop_order_table').' WHERE od_id='.ns_e($id));if(!$o)throw new DomainException('order_not_found');if($s['mode']==='test')return ['state'=>'test','creditedPoints'=>0];ny_validate_paid($o,$s);
 $k='youngcart:receipt:'.$id;$r=ns_doc($k,true);if($r)return $r['data'];$b=$s['benefits'];$rows=[];$q=ns_q('SELECT it_id,ct_qty,ct_price FROM '.ns_table('g5_shop_cart_table').' WHERE od_id='.ns_e($id));while($v=sql_fetch_array($q))$rows[]=['id'=>$v['it_id'],'quantity'=>(int)$v['ct_qty'],'price'=>(int)$v['ct_price']];$expected=$b['items'];usort($rows,fn($a,$c)=>strcmp($a['id'],$c['id']));usort($expected,fn($a,$c)=>strcmp($a['id'],$c['id']));if($rows!==$expected)throw new DomainException('order_items_changed');
 $providerRef=$s['mode']==='points'?'native-points:'.$id:$o['od_tno'];$tk='youngcart:transaction:'.hash('sha256',$providerRef);$tr=ns_doc($tk,true);if($tr&&$tr['data']['order']!==$id)throw new DomainException('transaction_reused');if(!$tr)ns_put($tk,'youngcart_transaction',['order'=>$id],0,$owner);
 $d=['state'=>'fulfilled','order'=>$id,'owner'=>$owner,'transaction'=>$providerRef,'creditedPoints'=>$b['points'],'days'=>$b['days'],'at'=>time()];
 if($b['points']>0&&insert_point($owner,$b['points'],'NOA 영카트 포인트 충전','noa_youngcart',$id,'paid')!==1)throw new RuntimeException('points_credit_failed');
 if($b['plan']!==null){$m=nr_member($owner);if(!in_array((int)$m['mb_level'],$b['plan']==='vip'?[2,3,4]:[7,8],true))throw new DomainException('membership_level_required');$g=ns_grant(['ownerId'=>$owner,'id'=>'youngcart:'.$id,'plan'=>$b['plan'],'durationDays'=>$b['days'],'method'=>'kcp'],$owner,time());$d['until']=$g['until'];nr_sync_member($owner,time());}ns_put($k,'youngcart_receipt',$d,0,$owner);return $d;});
}
function ny_sync_catalog():array{
 $catalog=ny_catalog();$category=['points'=>'n0','vip'=>'n1','goods'=>'n2'];$created=0;$updated=0;
 foreach(['points'=>'포인트 충전권','vip'=>'VIP 이용권','goods'=>'굿즈']as $kind=>$name){$id=$category[$kind];$row=ns_one('SELECT ca_id,ca_name FROM '.ns_table('g5_shop_category_table').' WHERE ca_id='.ns_e($id));if($row&&$row['ca_name']!==$name)throw new DomainException('category_conflict');if(!$row)ns_q('INSERT INTO '.ns_table('g5_shop_category_table').' SET ca_id='.ns_e($id).',ca_name='.ns_e($name).",ca_use=1,ca_skin='list.10.skin.php',ca_list_mod=4,ca_list_row=5,ca_img_width=225,ca_img_height=225");}
 foreach($catalog as $p){$marker='noa:'.$p['source'].':'.$p['sourceId'];$old=ns_one('SELECT * FROM '.ns_table('g5_shop_item_table').' WHERE it_id='.ns_e($p['id']));if($old&&$old['it_10']!==$marker)throw new DomainException('product_id_conflict');
 $img='';$src=realpath(G5_PATH.$p['image']);$base=realpath(G5_PATH.'/noa-assets');if($src&&$base&&str_starts_with($src,$base.'/')&&preg_match('/\.(webp|png|jpg|jpeg)$/i',$src,$m)){if(!is_dir(G5_DATA_PATH.'/item/noa'))mkdir(G5_DATA_PATH.'/item/noa',0755,true);$img='noa/'.$p['id'].'.'.strtolower($m[1]);if(!copy($src,G5_DATA_PATH.'/item/'.$img))throw new RuntimeException('image_copy_failed');}
 $description=htmlspecialchars($p['description'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');if($p['source']==='goods')$description.='<p>'.htmlspecialchars(($p['optionNote']??'').' '.($p['shippingNote']??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</p>';
 $fields=['ca_id'=>$category[$p['source']],'it_name'=>$p['title'],'it_basic'=>mb_substr($p['description'],0,255),'it_explan'=>$description,'it_mobile_explan'=>$description,'it_price'=>$p['price'],'it_use'=>0,'it_stock_qty'=>$p['orderable']?1000000:0,'it_sc_type'=>1,'it_buy_min_qty'=>1,'it_buy_max_qty'=>10,'it_point'=>0,'it_point_type'=>0,'it_notax'=>0,'it_img1'=>$img,'it_10'=>$marker];if($old){if($p['source']==='goods')foreach(['it_use','it_stock_qty','it_sc_type','it_buy_min_qty','it_buy_max_qty']as $keep)unset($fields[$keep]);if($img==='')unset($fields['it_img1']);}$sets=[];foreach($fields as $k=>$v)$sets[]='`'.$k.'`='.ns_e((string)$v);
 if($old){ns_q('UPDATE '.ns_table('g5_shop_item_table').' SET '.implode(',',$sets).' WHERE it_id='.ns_e($p['id']));$updated++;}else{ns_q('INSERT INTO '.ns_table('g5_shop_item_table').' SET it_id='.ns_e($p['id']).','.implode(',',$sets));$created++;}}
 $digitalIds=[];foreach($catalog as $p)if($p['source']!=='goods')$digitalIds[]=ns_e($p['id']);if($digitalIds)ns_q('UPDATE '.ns_table('g5_shop_item_table').' SET it_use=1 WHERE it_id IN ('.implode(',',$digitalIds).')');return ['count'=>count($catalog),'created'=>$created,'updated'=>$updated,'digital'=>10,'goodsAwaitingOptions'=>count($catalog)-10];
}
